            pass
        host = sp.hostname
        port = sp.port
        user = sp.username
        pwd = sp.password
        path = sp.path or ""
        query = parse_qs(sp.query or "")

        if user:
            user = unquote(user)
        if pwd:
            pwd = unquote(pwd)
        if host:
            host = unquote(host)

        if not host and sp.netloc and "," in sp.netloc:
