    except Exception:
        pass
    return out


def parse_odbc_connstr(s: str):
    out = {}
    parts = [p for p in s.split(";") if p.strip()]
    kv = {}
    for p in parts:
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        k = k.strip().lower()
        v = v.strip().strip("{}")
        if v:
            kv[k] = v
    if not kv:
        return out
    for hk in ("server", "data source", "addr", "address", "network address"):
