#!/usr/bin/env python3
import csv
import json
import os
import re
from urllib.parse import urlsplit, parse_qs, unquote

ROOT = "/workspace"
OUTPUT_CSV = os.path.join(ROOT, "db_migration_data.csv")

DB_TOKENS = {
    "db", "database", "postgres", "postgresql", "pg", "mysql", "mariadb",
    "mongo", "mongodb", "sqlserver", "mssql", "oracle", "sqlite", "cockroach",
    "crdb", "tidb", "redshift", "snowflake"
}

DB_URL_SCHEMES = {
    "postgres", "postgresql", "mysql", "mariadb", "mssql", "sqlserver",
    "oracle", "oci", "mongodb", "mongo", "sqlite", "cockroach", "cockroachdb",
    "crdb", "redshift", "snowflake"
}

CATEGORY_MAP = {
    "host": {"host", "hostname", "server", "addr", "address"},
    "port": {"port"},
    "username": {"user", "username", "uid", "userid", "user id"},
    "password": {"pass", "password", "pwd", "secret"},
    "db_name": {"name", "database", "dbname", "schema", "initial catalog"},
}

URL_TOKENS = {"url", "uri", "dsn", "connection", "conn", "connectionstring"}


def tokenize(s: str):
    return [t for t in re.split(r"[^a-zA-Z0-9]+", s.lower()) if t]


def token_contains_any(token: str, pool: set[str]) -> bool:
    return any(p in token for p in pool)


def is_db_related(tokens):
    if any(t in DB_TOKENS for t in tokens):
        return True
    # allow substrings like pghost, pgpassword, mysql_host
    return any(token_contains_any(t, DB_TOKENS) for t in tokens)


def classify_category(tokens, ancestor_db_related=False):
    for cat, keys in CATEGORY_MAP.items():
        key_match = any(k in tokens for k in keys) or any(token_contains_any(t, keys) for t in tokens)
        if key_match:
            # Only accept generic terms like 'name' if we are clearly db-related
            if cat == "db_name":
                if ancestor_db_related or is_db_related(tokens) or any(k in tokens for k in ("database", "dbname")):
                    return cat
            else:
                # host/port/username/password should be db-related to avoid false positives; allow ancestor flag
                if ancestor_db_related or is_db_related(tokens):
                    return cat
    return None


def is_url_like(tokens):
    return any(t in URL_TOKENS for t in tokens)


def parse_db_url(url: str):
    out = {}
    try:
        sp = urlsplit(url)
        scheme_base = (sp.scheme or "").split("+", 1)[0].lower()
        # If it's clearly not a DB scheme, bail early
        if scheme_base and scheme_base not in DB_URL_SCHEMES and sp.scheme:
            # still try best-effort in case
            pass
        host = sp.hostname
        port = sp.port
        user = sp.username
        pwd = sp.password
        path = sp.path or ""
        query = parse_qs(sp.query or "")

        if user:
            user = unquote(user)
        if pwd:
            pwd = unquote(pwd)
        if host:
            host = unquote(host)

        # Handle mssql host,port in netloc (comma)
        if not host and sp.netloc and "," in sp.netloc:
            netloc_cred_split = sp.netloc.rsplit("@", 1)
            hostpart = netloc_cred_split[-1]
            host_only, _, port_part = hostpart.partition(",")
            host = host_only or None
            try:
                port = int(port_part) if port_part else None
            except ValueError:
                port = None

        # Determine db name
        db_name = None
        if path and path != "/":
            db_name = os.path.basename(path.strip("/")) or None

        for key in ("database", "db", "dbname", "schema", "service_name", "sid"):
            if key in query and query[key]:
                qv = query[key][0]
                if isinstance(qv, str):
                    db_name = qv
                    break

        if sp.scheme.startswith("sqlite"):
            host = host or None
            port = port or None
            user = user or None
            pwd = pwd or None

        if host:
            out["host"] = host
        if port is not None:
            out["port"] = str(port)
        if user:
            out["username"] = user
        if pwd:
            out["password"] = pwd
        if db_name:
            out["db_name"] = db_name
    except Exception:
        pass
    return out


def parse_odbc_connstr(s: str):
    # Example: Driver={ODBC Driver 17 for SQL Server};Server=tcp:myserver,1433;Database=mydb;Uid=user;Pwd=pass
    out = {}
    parts = [p for p in s.split(";") if p.strip()]
    kv = {}
    for p in parts:
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        k = k.strip().lower()
        v = v.strip().strip("{}")
        if v:
            kv[k] = v
    if not kv:
        return out
    # Host
    for hk in ("server", "data source", "addr", "address", "network address"):
        if hk in kv:
            hostval = kv[hk]
            # strip protocol prefixes like tcp:
            if ":" in hostval and hostval.split(":", 1)[0].isalpha():
                hostval = hostval.split(":", 1)[1]
            # split host,port by comma
            host_only, sep, port_part = hostval.partition(",")
            if host_only:
                out["host"] = host_only
            if sep and port_part.isdigit():
                out["port"] = port_part
            break
    # Port
    if "port" in kv and "port" not in out:
        out["port"] = kv["port"]
    # Username
    for uk in ("uid", "user id", "user", "username"):
        if uk in kv:
            out["username"] = kv[uk]
            break
    # Password
    for pk in ("pwd", "password", "pass"):
        if pk in kv:
            out["password"] = kv[pk]
            break
    # Database name
    for dk in ("database", "initial catalog", "dbname"):
        if dk in kv:
            out["db_name"] = kv[dk]
            break
    return out


def looks_odbc_connstr(s: str) -> bool:
    s_low = s.lower()
    return (";" in s_low and "=" in s_low) and ("server=" in s_low or "data source=" in s_low or "address=" in s_low) and ("database=" in s_low or "initial catalog=" in s_low)


def parse_libpq_conninfo(s: str):
    # Example: host=localhost port=5432 dbname=mydb user=me password=secret
    out = {}
    # capture quoted values and unquoted tokens
    pattern = r"([A-Za-z_][A-Za-z0-9_]*)=(\"[^\"]*\"|\'[^\']*\'|[^\s]+)"
    kv = dict((m.group(1).lower(), m.group(2).strip().strip('"').strip("'")) for m in re.finditer(pattern, s))
    if not kv:
        return out
    if "host" in kv:
        out["host"] = kv["host"]
    if "port" in kv:
        out["port"] = kv["port"]
    for uk in ("user", "username"):
        if uk in kv:
            out["username"] = kv[uk]
            break
    for pk in ("password", "pass", "pwd"):
        if pk in kv:
            out["password"] = kv[pk]
            break
    for dk in ("dbname", "database", "db"):
        if dk in kv:
            out["db_name"] = kv[dk]
            break
    return out


def looks_libpq_conninfo(s: str) -> bool:
    s_low = s.lower()
    return ("host=" in s_low and ("dbname=" in s_low or "database=" in s_low)) or bool(re.search(r"\bdbname=", s_low))


def value_maybe_db_conn(s: str) -> dict:
    if not isinstance(s, str) or not s:
        return {}
    s = s.strip()
    # Try URL
    try:
        sp = urlsplit(s)
        scheme_base = (sp.scheme or "").split("+", 1)[0].lower()
        if sp.scheme and scheme_base in DB_URL_SCHEMES:
            parsed = parse_db_url(s)
            if parsed:
                return parsed
    except Exception:
        pass
    # Try ODBC-style conn string
    if looks_odbc_connstr(s):
        parsed = parse_odbc_connstr(s)
        if parsed:
            return parsed
    # Try libpq conninfo
    if looks_libpq_conninfo(s):
        parsed = parse_libpq_conninfo(s)
        if parsed:
            return parsed
    return {}


def parse_env_file(path):
    entries = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            lines = f.readlines()
    except Exception:
        return entries

    for raw in lines:
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.lower().startswith("export "):
            line = line[7:].lstrip()

        m = re.match(r"^([A-Za-z0-9_.-]+)\s*(=|:)\s*(.*)$", line)
        if not m:
            continue
        key = m.group(1)
        val = m.group(3).strip()

        quoted = False
        if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
            quoted = True
            val = val[1:-1]
        if not quoted and "#" in val:
            val = val.split("#", 1)[0].rstrip()

        tokens = tokenize(key)
        ancestor_db = is_db_related(tokens)

        # Handle URL-like values from key
        if is_url_like(tokens) and ancestor_db:
            parsed = parse_db_url(val)
            for cat, v in parsed.items():
                entries.append((path, ".env", key, cat, v))
            cat = classify_category(tokens, ancestor_db)
            if cat and cat not in parsed:
                entries.append((path, ".env", key, cat, val))
            continue

        cat = classify_category(tokens, ancestor_db)
        if cat:
            entries.append((path, ".env", key, cat, val))

        # Independently try to parse values that look like DB connection strings
        parsed_val = value_maybe_db_conn(val)
        for cat2, v2 in parsed_val.items():
            entries.append((path, ".env", key, cat2, v2))

    return entries


def walk_json(obj, path_keys, entries, file_path, ancestor_db_related=False):
    if isinstance(obj, dict):
        for k, v in obj.items():
            tokens = tokenize(str(k))
            is_db_here = ancestor_db_related or is_db_related(tokens)
            walk_json(v, path_keys + [str(k)], entries, file_path, is_db_here)
    elif isinstance(obj, list):
        for idx, v in enumerate(obj):
            walk_json(v, path_keys + [str(idx)], entries, file_path, ancestor_db_related)
    else:
        key_tokens = tokenize(path_keys[-1]) if path_keys else []
        key_path = ".".join(path_keys)
        text_val = "" if obj is None else str(obj)
        # URL-like leaf from key
        if is_url_like(key_tokens) and ancestor_db_related:
            parsed = parse_db_url(text_val)
            for cat, v in parsed.items():
                entries.append((file_path, "config.json", key_path, cat, v))
            cat = classify_category(key_tokens, ancestor_db_related)
            if cat and cat not in parsed:
                entries.append((file_path, "config.json", key_path, cat, text_val))
            return
        # Category by key name
        cat = classify_category(key_tokens, ancestor_db_related)
        if cat:
            entries.append((file_path, "config.json", key_path, cat, text_val))
        # Independently try to parse values that look like DB connection strings
        parsed_val = value_maybe_db_conn(text_val)
        for cat2, v2 in parsed_val.items():
            entries.append((file_path, "config.json", key_path, cat2, v2))


def parse_config_json(path):
    entries = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return entries
    walk_json(data, [], entries, path, ancestor_db_related=False)
    return entries


def find_target_files(root):
    targets = []
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            lower = fn.lower()
            if lower == "config.json" or lower.startswith(".env"):
                targets.append(os.path.join(dirpath, fn))
    return targets


def main():
    targets = find_target_files(ROOT)
    all_entries = []
    for path in targets:
        if path.lower().endswith("config.json"):
            all_entries.extend(parse_config_json(path))
        else:
            all_entries.extend(parse_env_file(path))

    # Deduplicate identical entries
    seen = set()
    deduped = []
    for e in all_entries:
        if e not in seen:
            seen.add(e)
            deduped.append(e)

    os.makedirs(os.path.dirname(OUTPUT_CSV), exist_ok=True)

    with open(OUTPUT_CSV, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["file_path", "source_type", "key_path", "category", "value"])
        for row in deduped:
            writer.writerow(row)

    print(f"Scanned {len(targets)} file(s). Extracted {len(deduped)} entrie(s). Output: {OUTPUT_CSV}")


if __name__ == "__main__":
    main()

