                entries.append((path, ".env", key, cat, v))
            cat = classify_category(tokens, ancestor_db)
            if cat and cat not in parsed:
                entries.append((path, ".env", key, cat, val))
            continue

        cat = classify_category(tokens, ancestor_db)
        if cat:
            entries.append((path, ".env", key, cat, val))

        parsed_val = value_maybe_db_conn(val)
        for cat2, v2 in parsed_val.items():
            entries.append((path, ".env", key, cat2, v2))

    return entries


def walk_json(obj, path_keys, entries, file_path, ancestor_db_related=False):
    if isinstance(obj, dict):
        for k, v in obj.items():
            tokens = tokenize(str(k))
            is_db_here = ancestor_db_related or is_db_related(tokens)
            walk_json(v, path_keys + [str(k)], entries, file_path, is_db_here)
    elif isinstance(obj, list):
        for idx, v in enumerate(obj):
            walk_json(v, path_keys + [str(idx)], entries, file_path, ancestor_db_related)
    else:
        key_tokens = tokenize(path_keys[-1]) if path_keys else []
        key_path = ".".join(path_keys)
        text_val = "" if obj is None else str(obj)
        if is_url_like(key_tokens) and ancestor_db_related:
            parsed = parse_db_url(text_val)
            for cat, v in parsed.items():
                entries.append((file_path, "config.json", key_path, cat, v))
            cat = classify_category(key_tokens, ancestor_db_related)
            if cat and cat not in parsed:
                entries.append((file_path, "config.json", key_path, cat, text_val))
            return
        cat = classify_category(key_tokens, ancestor_db_related)
        if cat:
            entries.append((file_path, "config.json", key_path, cat, text_val))
        parsed_val = value_maybe_db_conn(text_val)
        for cat2, v2 in parsed_val.items():
            entries.append((file_path, "config.json", key_path, cat2, v2))


def parse_config_json(path):
    entries = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return entries
    walk_json(data, [], entries, path, ancestor_db_related=False)
    return entries


def matches_includes_excludes(path, includes, excludes, root):
    rel = os.path.relpath(path, root)
    if includes:
        if not any(fnmatch(rel, inc) or path.startswith(os.path.join(root, inc)) for inc in includes):
            return False
    if excludes:
        for exc in excludes:
            if fnmatch(rel, exc) or path.startswith(os.path.join(root, exc)):
                return False
    return True


def find_target_files(root, includes=None, excludes=None):
    targets = []
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            lower = fn.lower()
            if lower == "config.json" or lower.startswith(".env"):
                full = os.path.join(dirpath, fn)
                if matches_includes_excludes(full, includes, excludes, root):
                    targets.append(full)
    return targets


def ensure_mode_600(path):
    try:
        os.chmod(path, 0o600)
    except Exception:
        pass


def write_csv(rows, output_path):
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["file_path", "source_type", "key_path", "category", "value"])
        for row in rows:
            writer.writerow(row)
    ensure_mode_600(output_path)


def write_csv_encrypted_gpg(rows, output_path, recipient=None, symmetric=False, passphrase_env=None):
    if shutil.which("gpg") is None:
        raise RuntimeError("gpg not found in PATH; cannot encrypt output")
    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["file_path", "source_type", "key_path", "category", "value"])
    for row in rows:
        writer.writerow(row)
    data = buf.getvalue().encode("utf-8")

    final_path = output_path if output_path.endswith(".gpg") else output_path + ".gpg"

    if recipient:
        cmd = ["gpg", "--batch", "--yes", "--encrypt", "--recipient", recipient, "-o", final_path]
        proc = subprocess.run(cmd, input=data, check=False)
    elif symmetric:
        cmd = ["gpg", "--batch", "--yes", "--symmetric", "--pinentry-mode", "loopback"]
        passphrase = None
        if passphrase_env:
            passphrase = os.environ.get(passphrase_env)
        if passphrase:
            cmd += ["--passphrase", passphrase]
        cmd += ["-o", final_path]
        proc = subprocess.run(cmd, input=data, check=False)
    else:
        raise RuntimeError("Encryption requested but no recipient or symmetric mode specified")

    if proc.returncode != 0:
        raise RuntimeError("gpg failed to encrypt output")

    ensure_mode_600(final_path)
    return final_path


def main():
    parser = argparse.ArgumentParser(description="Export DB connection data from .env and config.json files")
    parser.add_argument("--root", default=ROOT, help="Root directory to scan")
    parser.add_argument("--output", default=DEFAULT_OUTPUT, help="Output CSV path (unencrypted or pre-.gpg)")
    parser.add_argument("--include", action="append", default=None, help="Glob/path to include (relative to root). Can be used multiple times")
    parser.add_argument("--exclude", action="append", default=None, help="Glob/path to exclude (relative to root). Can be used multiple times")
    parser.add_argument("--include-username", action="store_true", help="Include username in output")
    parser.add_argument("--include-passwords", action="store_true", help="Include passwords in output (requires encryption or masking)")
    parser.add_argument("--mask-passwords", action="store_true", help="Mask passwords instead of omitting")
    parser.add_argument("--encrypt", action="store_true", help="Encrypt the output with gpg")
    parser.add_argument("--gpg-recipient", default=None, help="GPG recipient (key id/email) for encryption")
    parser.add_argument("--gpg-symmetric", action="store_true", help="Use symmetric GPG encryption (reads passphrase from env if provided)")
    parser.add_argument("--gpg-passphrase-env", default=None, help="Env var name containing passphrase for symmetric GPG encryption")
    parser.add_argument("--dry-run", action="store_true", help="Do not write any files; print summary only")

    args = parser.parse_args()

    includes = args.include or []
    excludes = args.exclude or []

    targets = find_target_files(args.root, includes, excludes)

    all_entries = []
    for path in targets:
        if path.lower().endswith("config.json"):
            all_entries.extend(parse_config_json(path))
        else:
            all_entries.extend(parse_env_file(path))

    # Deduplicate identical entries
    seen = set()
    deduped = []
    for e in all_entries:
        if e not in seen:
            seen.add(e)
            deduped.append(e)

    # Security: default to non-sensitive fields only
    allowed = {"host", "port", "db_name"}
    if args.include_username:
        allowed.add("username")

    final_rows = []
    for file_path, source_type, key_path, category, value in deduped:
        if category not in allowed and category != "password":
            continue
        if category == "password":
            if args.include_passwords:
                if args.mask_passwords or not args.encrypt:
                    # Mask unless encryption explicitly enabled without masking
                    value = "***MASKED***"
                # else: include as-is (encrypted output expected)
            else:
                continue
        final_rows.append((file_path, source_type, key_path, category, value))

    if args.dry_run:
        # Print summary without values
        counts = {}
        for _, _, _, category, _ in final_rows:
            counts[category] = counts.get(category, 0) + 1
        print(f"[DRY RUN] Scanned {len(targets)} file(s). Would export {len(final_rows)} row(s). Category counts: {counts}")
        print(f"[DRY RUN] Targets: {len(targets)}")
        for p in targets:
            print(f"  - {p}")
        return

    # Guard: prevent plaintext passwords unless explicitly masked or encrypted
    if any(r[3] == "password" for r in final_rows) and not args.encrypt and not args.mask_passwords:
        raise SystemExit("Refusing to write plaintext passwords. Use --encrypt or --mask-passwords or omit --include-passwords.")

    if args.encrypt:
        final_path = write_csv_encrypted_gpg(
            final_rows, args.output, recipient=args.gpg_recipient, symmetric=args.gpg_symmetric, passphrase_env=args.gpg_passphrase_env
        )
        print(f"Scanned {len(targets)} file(s). Exported {len(final_rows)} row(s). Encrypted output: {final_path}")
    else:
        write_csv(final_rows, args.output)
        print(f"Scanned {len(targets)} file(s). Exported {len(final_rows)} row(s). Output: {args.output}")


if __name__ == "__main__":
    main()

